<title>طبقات الأرض الجيولوجية</title>
<style>
  :root {
    --bg: #f4f8fc;
    --card: #ffffff;
    --ink: #1f2d3d;
    --muted: #5b6b7c;
    --line: #dfe8f2;
    --crust: #8a5f3c;
    --mantle: #c1572f;
    --outer:  #e8a33d;
    --inner:  #ffd463;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: "Segoe UI", Tahoma, "Noto Naskh Arabic", "Noto Sans Arabic", "Geeza Pro", Arial, sans-serif;
    background: var(--bg);
    color: var(--ink);
    line-height: 1.8;
  }
  header {
    background: linear-gradient(135deg, #123c66 0%, #1d4e89 55%, #2f6fb3 100%);
    color: #fff;
    text-align: center;
    padding: 2.2rem 1rem 1.6rem;
  }
  header h1 { font-size: 1.9rem; }
  header .subtitle { margin-top: .5rem; font-size: 1rem; opacity: .9; }

  main { max-width: 1000px; margin: 0 auto; padding: 1.6rem 1rem 2.5rem; }

  .card {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 12px;
    box-shadow: 0 1px 3px rgba(31,45,61,.06);
    padding: 1.2rem 1.3rem;
  }

  /* ===== Diagram ===== */
  .diagram-card { margin-bottom: 1.4rem; }
  .diagram {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    flex-wrap: wrap;
