{"command": "cd /home/agent/workspace && python3 - <<'EOF'
import numpy as np
from PIL import Image
import glob, os

def curl_score(F):
    dFdx = np.gradient(F, axis=1)  # columns = x
    dFdy = np.gradient(F, axis=0)  # rows = y (v, down)
    c = dFdx[...,1] - dFdy[...,0]  # curl_z = dFy/dx - dFx/dy
    return np.sqrt((c**2).mean())

rows = []
for p in sorted(glob.glob('textures/*.png')):
    a = np.asarray(Image.open(p)).astype(float)
    r = (a[...,0]-127.5)/127.5
    g = (a[...,1]-127.5)/127.5
    b = (a[...,2]-127.5)/127.5
    scores = {}
    for sr in (1,-1):
        for sg in (1,-1):
            F = np.stack((-sr*r/b, sg*g/b), axis=-1)
            scores[(sr,sg)] = curl_score(F)
    best = min(scores, key=scores.get)
    rows.append((os.path.basename(p), scores, best))

print(f"{'file':45s} |  (+,+)    (+,-)    (-,+)    (-,-)   | best")
for name, scores, best in rows:
    print(f"{name:45s} | {scores[(1,1)]:8.4f} {scores[(1,-1)]:8.4f} {scores[(-1,1)]:8.4f} {scores[(-1,-1)]:8.4f} | {best}")
EOF"}

